import axios from 'axios'

export default async function checkState() {
    await axios.post('/checkAdminServer', {token: authToken}).then(res => {
        setIsAdmin((res.data == 1 || res.data == 2) ? true : false)
        return
    }).catch(err => {
        setIsAdmin(false)
        return
    })
}
